// Kanji index for handwriting practice (generated by `npm run kanji`). Stroke paths are fetched
// per kanji from /kanji/<id>.json so they stay out of the page bundle and the Worker.
import data from './generated/kanji.json';

export type KanjiInfo = {
  id: string; char: string; level: string; on: string[]; kun: string[];
  meanings: {en: string; ru: string}; strokes: number;
};

export const kanjiList = data as KanjiInfo[];
const byId = new Map(kanjiList.map(kanji => [kanji.id, kanji]));

export function getKanji(id: string): KanjiInfo | undefined {return byId.get(id);}

const strokeCache = new Map<string, Promise<string[]>>();
export function loadStrokes(id: string): Promise<string[]> {
  let pending = strokeCache.get(id);
  if (!pending) {
    pending = fetch(`/kanji/${id}.json`).then(async response => {
      if (!response.ok) throw new Error(`Stroke data ${id}: ${response.status}`);
      const body = await response.json() as {strokes?: unknown};
      if (!Array.isArray(body.strokes) || !body.strokes.every(stroke => typeof stroke === 'string')) throw new Error(`Stroke data ${id}: bad format`);
      return body.strokes as string[];
    });
    pending.catch(() => strokeCache.delete(id));
    strokeCache.set(id, pending);
  }
  return pending;
}
